&lt;li style=&quot;margin-top: 0cm; margin-right: 0cm; margin-bottom: 8pt; line-height: 115%; font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Knowing is Half the Battle&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0cm; margin-right: 0cm; margin-bottom: 8pt; line-height: 115%; font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Break the Mold&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0cm; margin-right: 0cm; margin-bottom: 8pt; line-height: 115%; font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Take Charge&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0cm; margin-right: 0cm; margin-bottom: 8pt; line-height: 115%; font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Be Legendary&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0cm; margin-right: 0cm; margin-bottom: 8pt; line-height: 115%; font-size: 12pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Friendship is Magic&lt;/span&gt;&lt;/li&gt;
